/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { lineFromRequest } from './src/api.js';

const zeroResult = lineFromRequest({ sku: ' A ', quantity: '0' });
let errorMessage;
try {
  lineFromRequest({ sku: 'A', quantity: '' });
} catch (error) {
  errorMessage = error.message;
}
assert.deepEqual(zeroResult, { sku: 'A', quantity: 0, active: false });
assert.equal(errorMessage, 'invalid quantity');
const answer = {
  changed_file: 'src/quantity.js',
  zero_result: zeroResult,
  error_message: errorMessage,
};
await writeFile('answer.json', "'`${JSON.stringify(answer, null, 2)}'"\\n"'`);
assert.deepEqual(JSON.parse(await readFile('"'answer.json', 'utf8')), answer);
console.log(JSON.stringify(answer));
NODE"

